public static void main(String[] args) throws Exception {
    AReader input = new AReader();
    PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));
    String target = input.next();
    HashMap<String, Integer> hs = new HashMap<String, Integer>();
    hs.put("", 0);
    int n = input.nextInt();
    for (int i = 1; i <= n; ++i) {
        int x = input.nextInt();
        HashMap<String, Integer> may = new HashMap<String, Integer>();
        for (int j = 1; j <= x; ++j) {
            String string2 = input.next();
            for (String y : hs.keySet()) {
                String now = y + string2;
                if (target.startsWith(now)) {
                    int z = hs.get(y);
                    if (may.get(now) == null) {
                        may.put(now, z + 1);
                    } else {
                        int t = may.get(now);
                        if (t > z + 1)
                            may.put(now, z + 1);
                    }
                }
            }
        }
        for (String now : may.keySet()) {
            int y = may.get(now);
            if (!hs.containsKey(now) || y < hs.get(now)) {
                hs.put(now, y);
            }
        }
    }
    if (!hs.containsKey(target)) {
        out.print("-1");
    } else {
        out.print(hs.get(target));
    }
    out.flush();
    out.close();
}
